class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        vector<int> arr(colors.size()*2,0);
        int n=colors.size();
        for(int i=0;i<arr.size();i++){
            if(colors[i%n]!=colors[(i+1)%n]) arr[i]=1;
        }
        for(int i=1;i<arr.size();i++){
            arr[i]=arr[i]+arr[i-1];
        }
        int ans=0;
        for(int i=0;i<colors.size();i++){
            if(i==0){
            if(arr[i+(k-1)-1]==k-1) ans++;
            }
            else{
           if(arr[i+(k-1)-1]-arr[i-1]==k-1) ans++;
            }
        }
        return ans;
    }
};

class Solution {
public:
  int rangeand(vector<int> &bits,int len){
    int ans=0;
    for(int b=0;b<31;b++){
        if(bits[b]==len) ans+=(1<<b);
    }
    return ans;
  }
    long long atleastk(vector<int> &nums,int k){
        vector<int> bits(32,0);
        long long ans=0;
        int i=0;
        for(int j=0;j<nums.size();j++){
            for(int b=0;b<31;b++){
                if((1<<b)&nums[j]) bits[b]++;
            }
            while(i<=j&&rangeand(bits,j-i+1)<k){
                for(int b=0;b<31;b++){
                if((1<<b)&nums[i]) bits[b]--;
            }
                i++;
            }
            ans=ans+(j-i+1);
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        return atleastk(nums,k)-atleastk(nums,k+1);
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n=colors.size();
        vector<int>arr=colors;
        int idx=0;
        for(int cnt=2;cnt<=k;cnt++){
            arr.push_back(colors[idx]);
            idx++;
        }
        queue<int>q;
        for(int i=1;i<arr.size()-1;i++){
            if(arr[i]==arr[i-1]||arr[i]==arr[i+1])q.push(i);
        }
        int ans=0;
        for(int i=0;i<n;i++){
            while(!q.empty()&&q.front()<=i)q.pop();
            if(q.empty()||q.front()>=(i+k-1))ans++;
        }
        return ans;

    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<int>use(n);
        int l=-1;
        for(int i=0;i<n;i++){
            int curr=(nums[i]&k);
            if(curr<k)l=i;
            use[i]=l;
        }
        vector<vector<int>>v(33,vector<int>(n+1));
        for(int bit=0;bit<31;bit++){
            int num=(1<<bit);
            int l=-1;
            for(int i=0;i<n;i++){
                if(!(nums[i]&num))l=i;
                v[bit][i]=l;
            }
        }
        long long ans=0;
        for(int i=0;i<n;i++){
            if(use[i]==i)continue;
            int num=(k^nums[i]);
            int y=0;
            int idx=i;
            while(num>0){
                if((num&1))idx=min(idx,v[y][i]);
                num>>=1;
                y++;
            }
            int sz=(idx-use[i]);
            sz=max(sz,0);
            ans=(long long)ans+sz;
        }
        return ans;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(std::vector<int>& arr, int k) {
        std::vector<int> ret;
        int i = 0;
        int j = 1;
        int num_found = 0;
        int n = arr.size();

        while (j < n + k && i < n) {
            int temp_j = j;
            int temp_end = temp_j % n;
            while (arr[temp_end] != arr[(temp_end - 1 + n) % n] && temp_j < n + k - 1) {
                temp_j++;
                temp_end = temp_j % n;
            }

            num_found += std::max(temp_j - i - k + 1, 0);
            i = temp_j;
            j = i + 1;
        }
        return num_found;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int target) {
        int size = nums.size();
        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> currentResults; 
            if (nums[index] == target) {
                ++total;
            }
            currentResults[nums[index]] = 1;
            for (auto& [value, frequency] : previousResults) {
                long long newAndResult = value & nums[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                currentResults[newAndResult] += frequency;
            }

            previousResults = currentResults;
        }
        return total;
    }
};

class Solution {
public:
    bool helper(vector<int>&colors, int k, int idx){
        int curr = colors[idx];
        for(int i=1;i<k;i++){
            int next = colors[(idx+i)%(int)colors.size()];
            if(curr == next){
                return false;
            }
            else{   
                curr = next;
            }
        }
        return true;
    }
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
       for(int i=0;i<k;i++){
           colors.push_back(colors[i]);
       }
        int counter = 0;
        vector<int>pref(colors.size()+1,0);
        for(int i=1;i<colors.size();i++){
            pref[i] +=pref[i-1]+abs(colors[i]-colors[i-1]);
        }
        k-=1;
        for(int i=k+1;i<=colors.size()-1;i++){
            if(pref[i]-pref[i-k] == k){
                counter++;
            }
        }
        return counter;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        unordered_map<long long , long long>mp;
        long long counter = 0;
        for(auto it : nums){
            if(it == k){
                counter++;
            }
            unordered_map<long long, long long>freq;
            freq[it]=1;
            for(auto pairs : mp){
                long long curr = pairs.first&it;
                if(curr == k){
                    counter+=pairs.second;
                }
                freq[curr] += pairs.second;
            }
            mp = freq;

        }
        return counter;
    }
};

class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int length = colors.size();   
        int result = 0; 
        vector<int> groupWindow(length, 0); 
        for(int index = 0; index < length; index++){
            int value = (colors[(index) % length] ^ colors[(index + 1) % length]);
            groupWindow[index] = value;
        }

        k--; 
        int start = 0, end = 0;  
        int totalSize = length + k - 1; 
        while(end < totalSize){
            int startPos = start % length, endPos = end % length; 
            if(groupWindow[endPos] == 1){
                end++;
                if(end - start == k){
                    result++;
                    start++;      
                }
            }
            else{
                end++; 
                start = end; 
            }
        }
        return result;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& sequence, int target) {
        int n = sequence.size();
        long long count = 0;

        unordered_map<long long, long long> prevResults;

        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> currResults; 

            if (sequence[i] == target) {
                ++count;
            }
            currResults[sequence[i]] = 1;

            for (auto& [val, freq] : prevResults) {
                long long newAndResult = val & sequence[i];
                if (newAndResult == target) {
                    count += freq;
                }
                currResults[newAndResult] += freq;
            }

            prevResults = currResults;
        }

        return count;
    }
};

