    int[] prefixFunction(char[] s) {

        int n = s.length, pi[] = new int[n];

        for (int i = 1, j = 0; i < n; ++i) // j = pi[i-1] at the beginning of every iteration

        {

            while (j > 0 && s[i] != s[j])

                j = pi[j - 1];

            if (s[i] == s[j])

                ++j;

            pi[i] = j;

        }

        return pi;

    }

    class SparseTable {

        int[][] rmq;

        public SparseTable(int[] a) {

            int n = a.length;

            rmq = new int[32 - Integer.numberOfLeadingZeros(n)][];

            rmq[0] = a.clone();

            for (int i = 1; i < rmq.length; i++) {

                rmq[i] = new int[n - (1 << i) + 1];

                for (int j = 0; j < rmq[i].length; j++)

                    rmq[i][j] = op(rmq[i - 1][j], rmq[i - 1][j + (1 << (i - 1))]);

            }

        }

        public int query(int i, int j) {

            int k = 31 - Integer.numberOfLeadingZeros(j - i + 1);

            return op(rmq[k][i], rmq[k][j - (1 << k) + 1]);

        }

        int op(int a, int b) {

            return Math.max(a, b);

        }

    }

