    ArrayList<Long> findDiv(long N) {

        // gens all divisors of N

        ArrayList<Long> ls1 = new ArrayList<>();

        ArrayList<Long> ls2 = new ArrayList<>();

        for (int i = 1; i <= (int) (Math.sqrt(N) + 0.00000001); i++)

            if (N % i == 0) {

                ls1.add(1l * i);

                ls2.add(N / i);

            }

        Collections.reverse(ls2);

        for (long b : ls2)

            if (b != ls1.get(ls1.size() - 1))

                ls1.add(b);

        return ls1;

    }

    long power(long x, long y) {

        // 0^0 = 1

        long res = 1L;

        x = x % mod;

        while (y > 0) {

            if ((y & 1) == 1)

                res = (res * x) % mod;

            y >>= 1;

            x = (x * x) % mod;

        }

        return res;

    }

