        Queue<Integer> q = new LinkedList<>();

        q.add(st);

        D[st] = 0;

        while (!q.isEmpty()) {

            int p = q.poll();

            for (int a : g1[p]) {

                if (D[a] > D[p] + 1) {

                    D[a] = D[p] + 1;

