    public int numberOfAlternatingGroups(int[] color, int k) {
        int n= color.length;
        int[] arr= new int[n+k-1];
        for(int i=0;i<n;i++){
            arr[i]= color[i];
        }
        for(int i=n;i<arr.length;i++){
            arr[i]= arr[i-n];
        }
        int ans=0;
        int last=0;
        for(int i=0;i<n;i++){
            if(last==1){
                if(arr[i+k-1]==arr[i+k-2]){
                    last=0;
                    i= i+k-2;

                }else{
                    ans++;
                }
                continue;
            }
            int j=1;
            for(;j<k;j++){
                if(arr[i+j]==arr[i+j-1]){
                    break;
                }
            }
            if(j==k){
                last=1;
                ans++;
            }else{
                last=0;
                i= i+j-1;
            }
        }
        return ans;
    }

