        ArrayList<Integer> factors = new ArrayList<Integer>(); // take abs(N) in case of -ve integers

        int idx = 0, p = primes.get(idx);

        while (p * p <= N) {

            while (N % p == 0) {

                factors.add(p);

                N /= p;

            }

            p = primes.get(++idx);

        }

        if (N != 1) // last prime factor may be > sqrt(N)

