class Solution {
public:
    long long countSubarrays(vector<int>& arr, int target) {
        int n = arr.size();
        long long res = 0;
        unordered_map<long long, long long> prev;

        for (int i = 0; i < n; ++i) {
            processElement(arr, target, i, res, prev);
        }

        return res;
    }

private:
    void processElement(const vector<int>& arr, int target, int idx, long long& res, unordered_map<long long, long long>& prev) {
        unordered_map<long long, long long> curr;
        long long val = arr[idx];

        if (val == target) {
            ++res;
        }

        curr[val] = 1;

        for (auto& [v, freq] : prev) {
            long long newAnd = v & val;
            if (newAnd == target) {
                res += freq;
            }
            curr[newAnd] += freq;
        }

        prev = curr;
    }
};

