    long long get(int i, int j, int l, int r, int ind) {
        // cout << i << " " << j << endl;
        if (l<=i && r>=j) return prefix[ind];
        if (l > j || r < i) return LONG_LONG_MAX;

        int mid = (i+j)/2;
        return get(i, mid, l, r, 2*ind+1)&get(mid+1, j, l, r, 2*ind+2);
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        build(nums, 0, 0, n-1);

        long long ans = 0;

        cout << get(0, n-1, 0, n-1, 0) << endl;

        for(int i=0; i<n; i++) {
            int k1 = i, k2 = n-1;
            while(k1 < k2) {
                int mid = (k1 + k2)/2;
                if (get(0, n-1, i, mid, 0)>k) k1 = mid+1;
                else k2 = mid;
            }

            int i1 = k1, i2 = k2;

            k1 = i, k2 = n-1;
            while(k1 < k2) {
                int mid = (k1 + k2)/2;
                if (get(0, n-1, i, mid, 0)>(k-1)) k1 = mid+1;
                else k2 = mid;
            }

            // cout << i << " " << i1 << " " << k1 << endl;
            if (get(0, n-1, i, k1, 0) == k) k1++;
            ans += k1 - i1;
        }

        return ans;
    } 
};

class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int N = colors.length;
        int count = 0;
        if (k == 1) {
            return N;
        }

        int alternatingLength = 1;
        int i = 1;
        int[] extendedColors = new int[2 * N];
        System.arraycopy(colors, 0, extendedColors, 0, N);
        System.arraycopy(colors, 0, extendedColors, N, N);

        while (i < N + k - 1) {
            int current = i;
            int previous = i - 1;
            if (current >= extendedColors.length) {
                current -= N;
            }
            if (previous >= extendedColors.length) {
                previous -= N;
            }

            if (extendedColors[current] != extendedColors[previous]) {
                alternatingLength++;
            } else {
                alternatingLength = 1;
            }
            if (alternatingLength >= k) {
                count++;
            }

            i++;
        }

        return count;

    }
}

