        int num_found = 0;

        while (end_index < arr.size() + k && start_index < arr.size()) {
            int current_end = end_index % arr.size();

            while (arr[current_end] != arr[(current_end - 1 + arr.size()) % arr.size()] && (end_index < (arr.size() + k - 1))) {
                end_index++;
                current_end = end_index % arr.size();
            }

            num_found += max(end_index - start_index - k + 1, 0);
