object Solution {
  def countSubarrays(array: Array[Int], target: Int): Long = {
    val size = array.length
    var total: Long = 0
    var previousResults = HashMap.empty[Long, Long]
    for (index <- 0 until size) {
      var currentResults = HashMap.empty[Long, Long]

      if (array(index) == target) {
        total += 1
      }
      currentResults(array(index)) = 1
      for ((value, frequency) <- previousResults) {
        val newAndResult = value & array(index)
        if (newAndResult == target) {
          total += frequency
        }
        currentResults(newAndResult) = currentResults.getOrElse(newAndResult, 0L) + frequency
      }
      previousResults = currentResults
    }
    total
  }
}

