class Solution {
public:
    int binsg(int i,vector<int>&nums,int k,vector<vector<int>>&bits){
        int n = nums.size();
        int lo = i-1,hi=n-1;
        while(hi-lo>1){
            int mid = lo+((hi-lo)>>1);
            // find AND between i and mid
            int sm{};
            for(int j=0;j<32;++j){
                if(bits[mid+1][j]-bits[i][j]==mid-i+1)sm+=(1LL<<j);
            }
            if(sm>k)lo = mid;
            else hi=mid;
        }
        int sm{};
        for(int j=0;j<32;++j){
            if(bits[hi+1][j]-bits[i][j]==hi-i+1)sm+=(1LL<<j);
        }
        if(sm>k)lo=hi;
        return lo;
    }

    int binsl(int i,vector<int>&nums,int k,vector<vector<int>>&bits){
        int n = nums.size();
        int lo = i,hi=n;
        while(hi-lo>1){
            int mid = lo+((hi-lo)>>1);
            // find AND between i and mid
            int sm{};
            for(int j=0;j<32;++j){
                if(bits[mid+1][j]-bits[i][j]==mid-i+1)sm+=(1LL<<j);
            }
            if(sm<k)hi = mid;
            else lo=mid;
        }
        int sm{};
        for(int j=0;j<32;++j){
            if(bits[lo+1][j]-bits[i][j]==lo-i+1)sm+=(1LL<<j);
        }
        if(sm<k)hi=lo;
        return hi;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>>bits(n+1,vector<int>(32,0));
        for(int i=0;i<n;++i){
            for(int j=0;j<32;++j){
                bits[i+1][j]=bits[i][j];
                if((nums[i]>>j)&1)bits[i+1][j]++;
            }
        }   
        //binsg -> last index where AND is greater
        //binsl -> first index where AND is less

        long long ans{};

        for(int i=0;i<n;++i){
            int first_less = binsl(i,nums,k,bits);
            int last_greater = binsg(i,nums,k,bits);

            // cout << first_less << "," << last_greater << " ";
            ans+=max(0,first_less-last_greater-1);
        }

        return ans;
    }
};

