class Solution {
    public int numberOfAlternatingGroups(int[] colors, int groupSize) {
        int totalColors = colors.length;
        int validGroupCount = 0;

        if (groupSize == 1) {
            return totalColors;
        }

        int currentAlternatingLength = 1;
        int currentIndex = 1;
        while (currentIndex < totalColors + groupSize - 1) {
            int currentColorIndex = currentIndex % totalColors;
            int previousColorIndex = (currentIndex - 1) % totalColors;

            if (colors[currentColorIndex] != colors[previousColorIndex]) {
                ++currentAlternatingLength;
            } else {
                currentAlternatingLength = 1;
            }

            if (currentAlternatingLength >= groupSize) {
                ++validGroupCount;
            }

            ++currentIndex;
        }

        return validGroupCount;
    }
}

import java.util.HashMap;
import java.util.Map;

class Solution {
    public long countSubarrays(int[] numbers, int targetValue) {
        int arrayLength = numbers.length;
        long totalCount = 0;
        Map<Long, Long> previousBitwiseResults = new HashMap<>();

        for (int currentIndex = 0; currentIndex < arrayLength; ++currentIndex) {
            Map<Long, Long> currentBitwiseResults = new HashMap<>();

            if (numbers[currentIndex] == targetValue) {
                ++totalCount;
            }
            currentBitwiseResults.put((long)numbers[currentIndex], 1L);

            for (Map.Entry<Long, Long> entry : previousBitwiseResults.entrySet()) {
                long previousResult = entry.getKey();
                long frequency = entry.getValue();
                long newBitwiseAndResult = previousResult & numbers[currentIndex];

                if (newBitwiseAndResult == targetValue) {
                    totalCount += frequency;
                }
                currentBitwiseResults.put(newBitwiseAndResult, 
                    currentBitwiseResults.getOrDefault(newBitwiseAndResult, 0L) + frequency);
            }

            previousBitwiseResults = currentBitwiseResults;
        }

        return totalCount;
    }
}

