class AndQueue:
    def __init__(self):
        self.stack1 = []
        self.stack2 = []
        self.ands1 = [0xffffffff]
        self.ands2 = [0xffffffff]

    @staticmethod
    def _push(stack, ands, elem):
        and_ = ands[-1] & elem
        stack.append(elem)
        ands.append(and_)

    def push(self, elem):
        AndQueue._push(self.stack1, self.ands1, elem)

    def clear(self):
        self.stack1 = []
        self.stack2 = []
        self.ands1 = [0xffffffff]
        self.ands2 = [0xffffffff]

    def size(self):
        return len(self.stack1) + len(self.stack2)

    def get_and(self):
        return self.ands1[-1] & self.ands2[-1]

    def pop(self):
        assert self.size() > 0
        if not self.stack2:
            for elem in reversed(self.stack1):
                AndQueue._push(self.stack2, self.ands2, elem)
            self.stack1 = []
            self.ands1 = [0xffffffff]
        self.ands2.pop()
        return self.stack2.pop()

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        q_min = AndQueue()
        q_max = AndQueue()
        r_min = 0
        r_max = 0
        for i in range(n):
            if r_min < i:
                r_min = i 
                q_min.clear()
            if r_max < i:
                r_max = i
                q_max.clear()
            while r_min < n and (q_min.get_and() & nums[r_min]) > k and (q_min.get_and() & nums[r_min] & k) >= k:
                q_min.push(nums[r_min])
                r_min += 1
            while r_max < n and (q_max.get_and() & nums[r_max]) >= k and (q_max.get_and() & nums[r_max] & k) >= k:
                q_max.push(nums[r_max])
                r_max += 1
            ans += r_max - r_min
            if q_min.size() > 0:
                q_min.pop()
            if q_max.size() > 0:
                q_max.pop()
        return ans

