class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
    int n = colors.size();
    if (n < k) return 0;

    int count = 0;
    int altCount = 1;  // Number of alternating tiles in current window

    // Initialize the alternating count for the first k-1 elements
    for (int i = 1; i < k; ++i) {
        if (colors[i] != colors[i - 1]) {
            ++altCount;
        } else {
            altCount = 1;
        }
    }

    // Check the initial window
    if (altCount == k) {
        ++count;
    }

    // Use a sliding window to check the rest of the array
    for (int i = k; i < n + k - 1; ++i) {
        // Check if the new element maintains the alternating pattern
        if (colors[i % n] != colors[(i - 1) % n]) {
            ++altCount;
        } else {
            altCount = 1;
        }

        // Check if we have a valid alternating window
        if (altCount >= k) {
            ++count;
        }
    }

    return count;

    }
};

