class Solution {
#define pb push_back
public:
    int seg[400005];
    vector<int> v;

    void build(int id, int l, int r) {
        if (l == r) {
            seg[id] = v[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(id << 1, l, mid);
        build(id << 1 | 1, mid+1, r);
        seg[id] = seg[id<<1] & seg[id<<1 | 1];
    }

    int ask(int id, int l, int r, int L, int R) {
        //cout << "l = " << l << " r = " << r << endl;
        if (l > R || r < L) return -1;
        if (L <= l && r <= R) {
            return seg[id];
        } 
        int mid = (l + r) >> 1;
        return (ask(id<<1, l, mid, L, R) & ask(id<<1|1, mid+1, r, L, R));
    }

    bool check(int a, int k) {
        for (int i = 0; i < 32; i++) if ((k>>i) & 1) {
            if (!((a>>i)&1)) return true;
        }
        return false;
    }

    bool check2(int a, int k) {
        for (int i = 0; i < 32; i++) if ((k>>i) & 1) {
            if (!((a>>i)&1)) return false;
        }
        if (a > k) return true;
        return false;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = (int)nums.size();

        long long ans = 0;

        v.pb(0);
        for (int i:nums) v.pb(i);

        build(1, 1, n);

        for (int i = 1; i <= n; i++) {
            //cout << "i = " << i << endl;
            int l = i+1, r = n+1;
            while (l < r) {
                int mid = (l + r) >> 1;
                if (check(ask(1, 1, n, i, mid), k)) {
                    r = mid;
                } else {
                    l = mid + 1;
                }
            }
            int s = l - 1;
            //cout << "s = " << s << endl;
            l = i+1; r = n+1;
            while (l < r) {
                int mid = (l + r) >> 1;
                //cout << "mid = " << mid << " ask = " << ask(1, 1, n, i, mid) << endl;
                if (check2(ask(1, 1, n, i, mid), k)) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            int f = l;
            //cout << "f = " << f << endl;
            ans += max(0, s - f + 1);
            if (v[i] == k) ans++;
        }
        return ans;
    }
};

