class Solution {
public:
    void updateBits(vector<int> &store, int num) {
        int pos = 31;
        while(num) {
            store[pos] += (num & 1);
            num >>= 1;
            pos--;
        }
    }

    void updateNegativeBits(vector<int> &store, int num) {
        int pos = 31;
        while(num) {
            store[pos] = max(0, store[pos] - (num & 1));
            num >>= 1;
            pos--;
        }
    }

    bool isValid(int k, vector<int> &store) {
        int pos = 31;
        while(k) {
            if((k & 1) && store[pos] == 0)
                return false;
            k >>= 1;
            pos--;
        }
        return true;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ll ans = 0;
        unordered_map<ll, ll> prev;
        for (int i = 0; i < n; i++) {
            unordered_map<ll, ll> next; 
            if (nums[i] == k) ans++;
            next[nums[i]] = 1;

            for (auto it : prev) {
                if ((it.first & nums[i]) == k) ans += it.second;
                next[it.first & nums[i]] += it.second;
            }
            prev = next;
        }
        return ans;
    }
};

