#define ll	long long
int n;
struct SEG {
        ll x = -1;
        SEG() {
                x = -1;
        }
};

SEG operator+(const SEG &seg1, const SEG &seg2) {
        SEG ret;
        ret.x = (seg1.x & seg2.x);
        return ret;
}

class Solution {
public:
    vector<ll> v;

    vector<SEG> seg;

    SEG query(int qs, int qe, int si = 0, int ss = 0, int se = n - 1) {
            if (ss > qe || se < qs || qe < qs)
                    return SEG();
            if (ss >= qs && se <= qe)
                    return seg[si];
            int md = ss + (se - ss) / 2, rt = 2 * si + 1, lf = rt++;
            return query(qs, qe, lf, ss, md) + query(qs, qe, rt, md + 1, se);
    }
    void setNODE(int si = 0, int ss = 0, int se = n - 1){
            seg[si].x = v[ss];
    }
    void build(int si = 0, int ss = 0, int se = n - 1) {
            if (ss == se) {
                    setNODE(si, ss, se);
                    return;
            }
            int md = ss + (se - ss) / 2, lf = 2 * si + 1, rt = 2 * si + 2;
            build(lf, ss, md);
            build( rt, md + 1, se);
            seg[si] = seg[lf] + seg[rt];
    }

    long long countSubarrays(vector<int>& a, int k) {
        n=a.size();
        for (auto it:a) v.push_back(it);

        ll ans=0;
        seg.assign(4 * n + 2, SEG());
        build();

        for (int i=0; i<n; i++) {
            if (a[i] < k) continue;

            ll l=i, r=n, mid, L=i, R=i, q;
            while (l<r) {
                mid=l+r>>1;
                q=query(i, mid).x;
                if (q < k) r=mid;
                else {
                    if (q == k) R=mid;
                    l=mid+1;
                }
            }

            l=i, r=n;
            while (l<r) {
                mid=l+r>>1;
                q=query(i, mid).x;
                if (q > k) l=mid+1;
                else {
                    if (q == k) L=mid;
                    r=mid;
                }
            }

            if (query(i, L).x == k) ans+=R+1-L;
        }
        return ans;
    }
};

