class Solution {
    public int numberOfAlternatingGroups(int[] colors, int k) {
        int left = 0;
        int right = 0;
        int patternCount = 0;
        int n = colors.length;

        while (left < n) {
            if (right - left + 1 != k) {
                int parity = 0;
                for (int i = 0; i < k; i++) {
                    if (i == 0) {
                        parity = colors[(i + left) % n];
                    } else {
                        if (colors[(i + left) % n] == parity) {
                            right = i + left;
                            left = i + left;
                            break;
                        } else {
                            parity = colors[(i + left) % n];
                            right = i + left;
                        }
                    }
                }
                continue;
            } else {
                if (right - left + 1 == k) {
                    patternCount++;
                }
                if (left < n) {
                    if (k % 2 == 0 && colors[left] == colors[(right + 1) % n]) {
                        left++;
                        right++;
                    } else if (k % 2 == 1 && colors[left] != colors[(right + 1) % n]) {
                        left++;
                        right++;
                    } else {
                        left = right + 1;
                        right = right + 1;
                    }
                }
            }
        }
        return patternCount;
    }
}

class Solution {
