                int mid = (s+e)>>1;
                int x = get(mid, i);
                if(x==k)
                    lef=mid, e = mid-1;
                else if(x<k)
                    s = mid+1;
                else
                    e = mid-1;
            }

            s=0, e=i;
            while(s<=e)
            {
                int mid = (s+e)>>1;
