class SEG {
    vector<int> tree;
public:
    SEG(int n) {
        tree.resize(4 * n + 1, 0);
    }

    void build(int node, int start, int end, vector<int>& A) {
        if (start == end) {
            tree[node] = A[start];
        } else {
            int mid = (start + end) / 2;
            build(2 * node + 1, start, mid, A);
            build(2 * node + 2, mid + 1, end, A);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return INT_MAX;
        }

        if (l <= start && end <= r) {
            return tree[node];
        }

        int mid = (start + end) / 2;
        int p1 = query(2 * node + 1, start, mid, l, r);
        int p2 = query(2 * node + 2, mid + 1, end, l, r);
        int res = p1 & p2;
        return res;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long count = 0;
        int n = nums.size();
        SEG sgt(n);
        sgt.build(0, 0, n - 1, nums);

        for (int i = 0; i < n; i++) {
            int start = i;
            int end = n - 1;
            int ans1 = -1;

            while (start <= end) {
                int mid = start + (end - start) / 2;
                int val = sgt.query(0, 0, n - 1, i, mid);
                if (val < k) {
                    end = mid - 1;
                } else if (val > k) {
                    start = mid + 1;
                } else {
                    ans1 = mid;
                    end = mid - 1;
                }
            }

            start = i;
            end = n - 1;
            int ans2 = -1;

            while (start <= end) {
                int mid = start + (end - start) / 2;
                int val = sgt.query(0, 0, n - 1, i, mid);
                if (val > k) {
                    start = mid + 1;
                } else if (val < k) {
                    end = mid - 1;
                } else {
                    ans2 = mid;
                    start = mid + 1;
                }
            }

            if (ans1 != -1 && ans2 != -1) {
                count += 1LL * (ans2 - ans1 + 1);
            }
        }

        return count;
    }
};

