						int d=1<<j;
						if((k&d)!=0){
							int bit=pre[mid][j];
							if(i>0)bit-=pre[i-1][j];
							if(mid-i+1!=bit)fl=0;
						}else {
							int bit=pre[mid][j];
							if(i>0)bit-=pre[i-1][j];

							if(mid-i+1==bit)fl=2;
						}
					}
                    if(fl==2){
                        l=mid+1;
                    }else
					if(fl==0){
						r=mid-1;
					}else {
						l=mid+1;mx=mid;
					}
				}

				if(mx!=-1){
					l=i;r=mx;
					while (l<=r){
						int mid=(l+r)/2;int fl=1;
						for (int j = 0; j <32 ; j++) {
							int d=1<<j;
							if((k&d)!=0){
								int bit=pre[mid][j];
								if(i>0)bit-=pre[i-1][j];
								if(mid-i+1!=bit)fl=0;
							}else {
								int bit=pre[mid][j];
								if(i>0)bit-=pre[i-1][j];
								if(mid-i+1==bit)fl=0;
