class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans=0;
        int n=nums.size();
        vector<vector<int>> dp(31, vector<int> (n+1, 0));
        for(int i=0; i<n; i++)
        {
            for(int j=0; j<31; j++)
            {
                dp[j][i+1]=dp[j][i]+((nums[i]>>j)&1);
            }
        }

        int l=0;
        int r=0;
        while(l<n)
        {
            // cout<<l<<" "<<r<<" = "<<ans<<endl;

            int s=-1;
            while(r<n && (nums[r]&k)>=k) 
            {
                // cout<<"  r - "<<r<<endl;
                if(s==-1)
                {
                    int andval=0;
                    for(int j=0; j<31; j++)
                    {
                        if(dp[j][r+1]-dp[j][l]==r+1-l) andval^=(1<<j);
                    }
                    if(andval==k) s=r;
                }

                ++r;
            }
            if(s!=-1) ans+=r-s;
            else
            {
                l=r=l+1;
                continue;
            }
            // cout<<"  "<<l<<" - "<<s<<" - "<<r<<endl;
            ++l;

            while(l<r)
            {
                s=max(s, l);
                while(s<r)
                {
                    int andval=0;
                    for(int j=0; j<31; j++)
                    {
                        // cout<<"    j = "<<j<<" - "<<dp[j][s+1]<<", "<<dp[j][l]<<endl;
                        if(dp[j][s+1]-dp[j][l]==s+1-l) andval|=(1<<j);
                    }
                    // cout<<"    "<<andval<<endl;
                    if(andval==k) break;
                    ++s;
                }
                // cout<<"  "<<l<<" - "<<s<<" - "<<r<<endl;
                if(s==r)
                {
                    l=r;
                    break;
                }
                ans+=r-s;
                ++l;
            }
        }

        return ans;
    }
};

class Solution {
    public int numberOfAlternatingGroups(int[] Arr, int k) {
        int n = Arr.length; 

        int res = 0; 

        int len = 1; 
        for(int i = 1; i < n + k - 1; i++) { 

        	int curr = i; 
            int prev = i - 1; 

            curr = curr % n;
            prev = prev % n;

            if (Arr[curr] != Arr[prev]) { 
                len++; 
            } else { 
                len = 1; 
            } 

            if (len >= k) { 
                res++; 
            } 
        } 

       return res;
    }
}

class Solution {
    public long countSubarrays(int[] Arr, int k) {
        Map<Integer, Integer> p = new HashMap<>();

        int n = Arr.length;
        long res = 0;

        for (int i = 0; i < n; ++i) {
            Map<Integer, Integer> c = new HashMap<>();

            c.put(Arr[i], 1);
            if (Arr[i] == k) {
                res++;
            }

            for (int key : p.keySet()) {

                int freq = p.get(key);
                int nval = key & Arr[i];

                if (nval == k) {
                    res += freq;
                }
                c.put(nval, c.getOrDefault(nval, 0) + freq);
            }

            p = c;
        }
        return res;
    }
}

