class segmenttree{
public:
    vector<int> tree;
    vector<int> v;

    segmenttree(vector<int> val){
        tree.resize(val.size()*4);

        buildTree(0,0,val.size()-1,val);
    }

    void buildTree(int tidx, int lo, int hi,vector<int> &val){

	if(lo==hi){
		tree[tidx] = val[hi];
		return;
	}

	int mid = (lo+hi)/2;

	buildTree(2*tidx+1, lo, mid,val);
	buildTree(2*tidx+2, mid+1, hi,val);

	tree[tidx] = tree[2*tidx+1] & tree[2*tidx+2];

}

int query(int tidx, int lo, int hi, int L, int R){

	if( R<lo || L>hi )
		return (1ll<<32)-1;

	if( lo>=L && hi<=R )
		return tree[tidx];

	int mid = (lo+hi)/2;
	int leftans = query(2*tidx+1, lo, mid, L, R);
	int rightans = query(2*tidx+2, mid+1, hi, L, R);

	return leftans & rightans;

}
};



class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        segmenttree st(nums);
        long long ans=0;
        for(int i=0;i<nums.size();i++){
            int start=i;
            int end=nums.size()-1;
            int lim=-1;
            while(start<=end){
                int mid=start+(end-start)/2;
                int value=st.query(0,0,nums.size()-1,i,mid);
                // cout<<"i="<<i<<" mid="<<mid<<" value="<<value<<endl;
                if(value<k){
                    end=mid-1;
                }
                else if(value>k){
                    start=mid+1;
                }
                else{
                    lim=mid;
                    start=mid+1;
                }
            }

            if(lim!=-1){
                start=i;
                end=nums.size()-1;
                int lim2=-1;
                while(start<=end){
                    int mid=start+(end-start)/2;
                    int value=st.query(0,0,nums.size()-1,i,mid);
                    // cout<<"i="<<i<<" mid="<<mid<<" value="<<value<<endl;
                    if(value<k){
                        end=mid-1;
                    }
                    else if(value>k){
                        start=mid+1;
                    }
                    else{
                        lim2=mid;
                        end=mid-1;
                    }
                }
                ans+=(lim-lim2+1)*1ll;
            }
        }
        return ans;
    }
};

