class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        // Extend the colors vector
        extendColors(colors, k);

        return countAlternatingGroups(colors, k);
    }

private:
    void extendColors(vector<int>& colors, int k) {
        colors.insert(colors.end(), colors.begin(), colors.begin() + k - 1);
    }

    int countAlternatingGroups(const vector<int>& colors, int k) {
        int res = 0;
        int n = 1;

        for (int i = 1; i < colors.size(); i++) { // Start from 1 to avoid out of bounds for colors[i-1]
            n = (colors[i] != colors[i - 1]) ? n + 1 : 1;
            if (n >= k) {
                res++;
            }
        }

        return res;
    }
};

class Solution {
    int n;
    long long count;
    unordered_map<int, int> previous;
public:
    long long countSubarrays(vector<int>& nums, int k) {
         n = nums.size();
         count = 0;


        for (int i = 0; i < n; ++i) {
            std::unordered_map<int, int> current;

            if (nums[i] == k) {
                count += 1;
            }
            current[nums[i]] = 1;

            for (const auto& [key, value] : previous) {
                int new_key = key & nums[i];
                if (new_key == k) {
                    count += value;
                }
                if (current.find(new_key) != current.end()) {
                    current[new_key] += value;
                } else {
                    current[new_key] = value;
                }
            }

            previous = current;
        }

        return count;
    }
};
